svg.script:
//
    (function() {
      'use strict';

      var state = {
        mode: 'territories',
        selectedTerritory: 'ilio',
        isFlipped: false
      };

      var territoryData = {
        ilio: {
          title: "1. ÍLIO (Território Superior)",
          badgeClass: "a12p6h-badge-lio",
          color: "var(--a12p6h-ilio-light, #f472b6)",
          desc: "O <b>Ílio</b> forma a porção <b>superior (teto acetabular)</b> e a asa ilíaca. Suporta a carga axial transmitida da coluna e do sacro para o fêmur.",
          lm: [
            "• Teto Acetabular (Dome / Cúpula articular)",
            "• Crista Ilíaca e EIAS / EIAI (Anteriores)",
            "• Porção Superior da Incisura Isquiática Maior",
            "• Integra a Coluna Anterior e Posterior de Judet"
          ],
          judet: "<b>Participação nas Colunas:</b> Fornece a porção superior e o teto para a <b>Coluna Anterior</b> (Linha Iliopúbica) e para a <b>Coluna Posterior</b> (Linha Ilioisquiática)."
        },
        isquio: {
          title: "2. ÍSQUIO (Território Posterior)",
          badgeClass: "a12p6h-badge-isquio",
          color: "var(--a12p6h-isquio-light, #fb923c)",
          desc: "O <b>Ísquio</b> forma a porção <b>posterior e inferior</b> do acetábulo. Caracteriza-se pela proeminente Espinha Isquiática e pelo robusto Túber Isquiático.",
          lm: [
            "• Parede Posterior e Coluna Posterior",
            "• Espinha Isquiática (Ponto de referência posterior)",
            "• Incisura Isquiática Menor (Inferior à espinha)",
            "• Túber Isquiático (Apoio ao sentar)"
          ],
          judet: "<b>Coluna Posterior de Judet:</b> Formada pelo Ísquio + porção ilíaca posterior + parede posterior. Trajetórias de fratura afetam a estabilidade posterior da cabeça femoral."
        },
        pubis: {
          title: "3. PÚBIS (Território Anterior)",
          badgeClass: "a12p6h-badge-pubis",
          color: "var(--a12p6h-pubis-light, #38bdf8)",
          desc: "O <b>Púbis</b> forma a porção <b>anterior e inferior</b>. Seus ramos delimitam a parede anterior do acetábulo e a margem anterior do Forame Obturado.",
          lm: [
            "• Ramo Superior do Púbis (Coluna Anterior)",
            "• Ramo Inferior do Púbis (Arco Púbico)",
            "• Corpo do Púbis e Sínfise Púbica (Anterior)",
            "• Pecten do Púbis e Crista Púbica"
          ],
          judet: "<b>Coluna Anterior de Judet:</b> Formada pelo Ramo Superior do Púbis + metade anterior do Ílio (Linha Iliopúbica). Fundamental para a contenção anterior da cabeça femoral."
        },
        't-junction': {
          title: "O 'T' / Cartilagem Trirrradiada",
          badgeClass: "a12p6h-badge-lio",
          color: "var(--a12p6h-t-line, #facc15)",
          desc: "A <b>Cartilagem Trirrradiada</b> em forma de 'Y' ou 'T' une os 3 ossos na infância e se funde na puberdade, formando o centro da fossa acetabular.",
          lm: [
            "• Haste Superior: Separa Ílio e Púbis/Ísquio",
            "• Haste Anterior: Divisão Ilio-Púbica",
            "• Haste Posterior: Divisão Ilio-Isquiática",
            "• Fossa Acetabular Central (Não-articular)"
          ],
          judet: "<b>Centro Radiológico de Judet:</b> As linhas do 'T' correspondem aos eixos anatômicos que dividem as fraturas elementares (transversas, 'T-shaped', coluna dupla)."
        }
      };

      var svgRoot = document.getElementById('a12p6h-svg');
      var shapeIlio = document.getElementById('a12p6h-shape-ilio');
      var shapeIsquio = document.getElementById('a12p6h-shape-isquio');
      var shapePubis = document.getElementById('a12p6h-shape-pubis');
      var tStems = [
        document.getElementById('a12p6h-t-stem-sup'),
        document.getElementById('a12p6h-t-stem-ant'),
        document.getElementById('a12p6h-t-stem-post')
      ];

      var panelTitle = document.getElementById('a12p6h-panel-title');
      var panelDesc = document.getElementById('a12p6h-panel-desc');
      var panelJudet = document.getElementById('a12p6h-panel-judet');
      var lmElements = [
        document.getElementById('a12p6h-lm-1'),
        document.getElementById('a12p6h-lm-2'),
        document.getElementById('a12p6h-lm-3'),
        document.getElementById('a12p6h-lm-4')
      ];

      var transformGroup = document.getElementById('a12p6h-pelvis-transform-group');
      var lblRight = document.getElementById('a12p6h-lbl-right');
      var lblLeft = document.getElementById('a12p6h-lbl-left');
      var viewSideTxt = document.getElementById('a12p6h-view-side-txt');

      var tabs = [
        document.getElementById('a12p6h-tab-1'),
        document.getElementById('a12p6h-tab-2'),
        document.getElementById('a12p6h-tab-3')
      ];

      var btnFlip = document.getElementById('a12p6h-btn-flip');

      function updatePanelContent(key) {
        var data = territoryData[key] || territoryData['ilio'];
        panelTitle.textContent = data.title;
        panelTitle.style.fill = data.color;
        panelDesc.innerHTML = data.desc;
        panelJudet.innerHTML = data.judet;

        for (var i = 0; i < 4; i++) {
          if (lmElements[i]) {
            lmElements[i].textContent = data.lm[i] || '';
          }
        }
      }

      function highlightTerritory(key) {
        state.selectedTerritory = key;

        [shapeIlio, shapeIsquio, shapePubis].forEach(function(el) {
          if (el) {
            el.classList.remove('a12p6h-selected', 'a12p6h-dimmed');
          }
        });

        tStems.forEach(function(stem) {
          if (stem) stem.classList.remove('a12p6h-highlight');
        });

        if (key === 'ilio' && shapeIlio) {
          shapeIlio.classList.add('a12p6h-selected');
          if (shapeIsquio) shapeIsquio.classList.add('a12p6h-dimmed');
          if (shapePubis) shapePubis.classList.add('a12p6h-dimmed');
        } else if (key === 'isquio' && shapeIsquio) {
          shapeIsquio.classList.add('a12p6h-selected');
          if (shapeIlio) shapeIlio.classList.add('a12p6h-dimmed');
          if (shapePubis) shapePubis.classList.add('a12p6h-dimmed');
        } else if (key === 'pubis' && shapePubis) {
          shapePubis.classList.add('a12p6h-selected');
          if (shapeIlio) shapeIlio.classList.add('a12p6h-dimmed');
          if (shapeIsquio) shapeIsquio.classList.add('a12p6h-dimmed');
        } else if (key === 't-junction') {
          tStems.forEach(function(stem) {
            if (stem) stem.classList.add('a12p6h-highlight');
          });
        }

        updatePanelContent(key);
      }

      function toggleFlip() {
        state.isFlipped = !state.isFlipped;

        if (state.isFlipped) {
          transformGroup.setAttribute('transform', 'translate(700, 0) scale(-1, 1)');
          lblRight.textContent = "POSTERIOR (Ísquio)";
          lblLeft.textContent = "ANTERIOR (Púbis)";
          viewSideTxt.textContent = "Hemipelve Esquerda — Visão Lateral Externa";
        } else {
          transformGroup.setAttribute('transform', 'translate(0, 0) scale(1, 1)');
          lblRight.textContent = "ANTERIOR (Púbis)";
          lblLeft.textContent = "POSTERIOR (Ísquio)";
          viewSideTxt.textContent = "Hemipelve Direita — Visão Lateral Externa";
        }
      }

      function setMode(modeName) {
        state.mode = modeName;
        tabs.forEach(function(tab) {
          if (tab) {
            if (tab.getAttribute('data-mode') === modeName) {
              tab.classList.add('a12p6h-active');
            } else {
              tab.classList.remove('a12p6h-active');
            }
          }
        });

        if (modeName === 'columns') {
          highlightTerritory('ilio');
          panelTitle.textContent = "Colunas Anatômicas de Judet";
          panelDesc.innerHTML = "As <b>Colunas de Judet</b> dividem o acetábulo em dois pilares principais em formato de 'V' invertido com vértice na asa do ílio.";
        } else if (modeName === 'mirror') {
          highlightTerritory('t-junction');
          panelTitle.textContent = "Modo Anti-Espelhamento";
          panelDesc.innerHTML = "Clique no botão <b>'Alternar Lado'</b> para verificar como a regra se mantém em qualquer hemipelve: <b>Púbis é SEMPRE Anterior</b>.";
        } else {
          highlightTerritory('ilio');
        }
      }

      if (shapeIlio) {
        shapeIlio.addEventListener('click', function() { highlightTerritory('ilio'); });
      }
      if (shapeIsquio) {
        shapeIsquio.addEventListener('click', function() { highlightTerritory('isquio'); });
      }
      if (shapePubis) {
        shapePubis.addEventListener('click', function() { highlightTerritory('pubis'); });
      }

      var acetabulumCup = document.getElementById('a12p6h-acetabulum-cup');
      if (acetabulumCup) {
        acetabulumCup.style.cursor = 'pointer';
        acetabulumCup.addEventListener('click', function() { highlightTerritory('t-junction'); });
      }

      if (btnFlip) {
        btnFlip.addEventListener('click', toggleFlip);
      }

      tabs.forEach(function(tab) {
        if (tab) {
          tab.addEventListener('click', function() {
            var mode = this.getAttribute('data-mode');
            setMode(mode);
          });
        }
      });

      highlightTerritory('ilio');

    })();
  //
